import { existsSync, mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";
import { listWorkspacePackages, normalizePath, readJson, repoRoot } from "./lib/repo.mjs";

const generatedRegistryComment = "// Generated by scripts/sync-workspace-metadata.mjs. Do not edit by hand.\n";
const generatedSchemaComment =
  "// Generated by scripts/sync-workspace-metadata.mjs from schema.sql. Do not edit by hand.\n";
const tsconfigBaseComment =
  "// Workspace tsconfigs extend this file or tsconfig.vitest.json; root tsconfig.json is only the editor/solution entry.\n";
const legacyTsconfigCompilerOptions = [
  "charset",
  "importsNotUsedAsValues",
  "keyofStringsOnly",
  "noImplicitUseStrict",
  "noStrictGenericChecks",
  "out",
  "preserveValueImports",
  "suppressExcessPropertyErrors",
  "suppressImplicitAnyIndexErrors",
];
const ts7CompatibleCompilerOptions = {
  target: "ES2022",
  module: "Preserve",
  moduleResolution: "Bundler",
  lib: ["ES2022", "DOM", "DOM.Iterable"],
  jsx: "react-jsx",
  strict: true,
  skipLibCheck: true,
  esModuleInterop: true,
  forceConsistentCasingInFileNames: true,
  resolveJsonModule: true,
  allowSyntheticDefaultImports: true,
  noEmit: true,
  baseUrl: ".",
};
const appBuildSemanticCompilerOptions = ["verbatimModuleSyntax"];

function buildLegacyPlatformRuntimeRegistryPaths(rootDir) {
  return [
    path.join(rootDir, "infrastructure", "platform-runtime", "api-context-registry.generated.ts"),
    path.join(rootDir, "infrastructure", "platform-runtime", "web-context-registry.generated.ts"),
  ];
}

function buildGeneratedRegistryOutputs(rootDir) {
  return [
    {
      kind: "api",
      hostName: "platform-api",
      outputPath: path.join(rootDir, "deployables", "platform-api", "src", "generated", "api-context-registry.ts"),
    },
    {
      kind: "worker",
      hostName: "platform-worker",
      outputPath: path.join(
        rootDir,
        "deployables",
        "platform-worker",
        "src",
        "generated",
        "worker-context-registry.ts",
      ),
    },
    {
      kind: "web",
      hostName: "admin-web",
      outputPath: path.join(rootDir, "deployables", "admin-web", "app", "generated", "web-context-registry.ts"),
    },
    {
      kind: "web",
      hostName: "marketplace-web",
      outputPath: path.join(rootDir, "deployables", "marketplace", "app", "generated", "web-context-registry.ts"),
    },
    {
      kind: "web",
      hostName: "public-web",
      outputPath: path.join(rootDir, "deployables", "public-web", "app", "generated", "web-context-registry.ts"),
    },
  ];
}

function sortObjectKeys(value) {
  return Object.fromEntries(Object.entries(value).sort(([left], [right]) => left.localeCompare(right)));
}

function normalizeRelative(filePath, rootDir) {
  return `./${normalizePath(path.relative(rootDir, filePath))}`;
}

function normalizeImportPath(fromFile, toFile) {
  const relativePath = normalizePath(path.relative(path.dirname(fromFile), toFile));
  return relativePath.startsWith(".") ? relativePath : `./${relativePath}`;
}

function toExportsObject(exportsField) {
  if (typeof exportsField === "string") {
    return { ".": exportsField };
  }

  return exportsField ?? {};
}

function buildTsconfigPaths(workspaces, rootDir) {
  const aliases = {};

  for (const workspace of workspaces) {
    const exportsField = toExportsObject(workspace.packageJson.exports);

    for (const [exportKey, exportTarget] of Object.entries(exportsField)) {
      if (typeof exportTarget !== "string") {
        continue;
      }

      const targetPath = normalizeRelative(path.join(workspace.dir, exportTarget.replace(/^\.\//, "")), rootDir);

      if (exportKey === ".") {
        aliases[workspace.name] = [targetPath];
        continue;
      }

      const exportSuffix = exportKey.replace(/^\.\//, "");
      aliases[`${workspace.name}/${exportSuffix}`] = [targetPath];
    }
  }

  return sortObjectKeys(aliases);
}

function listBoundedContexts(workspaces) {
  return workspaces
    .filter((workspace) => workspace.root === "bounded-contexts")
    .map((workspace) => {
      const manifestPath = path.join(workspace.dir, "context.json");
      const manifest = readJson(manifestPath);

      return {
        contextName: manifest.contextName,
        dirName: workspace.dirName,
        packageName: workspace.name,
        manifest,
        manifestPath,
      };
    })
    .sort((left, right) => left.contextName.localeCompare(right.contextName));
}

function toIdentifier(value) {
  const normalized = String(value)
    .replace(/[^A-Za-z0-9_$]+(.)?/g, (_match, next) => (next ? next.toUpperCase() : ""))
    .replace(/^[^A-Za-z_$]+/, "");

  return normalized.length > 0 ? normalized : "context";
}

function buildApiRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter(
    (context) =>
      context.manifest.apiDeployables?.includes(hostName) ||
      context.manifest.sourceRuntimeDeployables?.includes(hostName) ||
      context.manifest.sourceRuntimeProfiles?.length > 0,
  );
  const contextImports = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `import { contextManifest as ${identifier}Manifest, module as ${identifier}Module } from "${context.packageName}";`;
  });
  const entries = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${identifier}Manifest,
    module: ${identifier}Module,
  },`;
  });

  return `${generatedRegistryComment}
${contextImports.join("\n")}

export const apiContextRegistry = [
${entries.join("\n")}
] as const;
`;
}

function buildWorkerRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter(
    (context) =>
      context.manifest.runtimeDeployables?.includes(hostName) ||
      context.manifest.sourceRuntimeDeployables?.includes(hostName) ||
      context.manifest.sourceRuntimeProfiles?.length > 0,
  );
  const contextImports = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `import { contextManifest as ${identifier}Manifest, module as ${identifier}Module } from "${context.packageName}";`;
  });
  const entries = activeContexts.map((context) => {
    const identifier = toIdentifier(context.contextName);
    return `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${identifier}Manifest,
    module: ${identifier}Module,
  },`;
  });

  return `${generatedRegistryComment}
${contextImports.join("\n")}

export const workerContextRegistry = [
${entries.join("\n")}
] as const;
`;
}

function contributesToWebHost(context, hostName) {
  return (
    context.manifest.deployableContributions?.some((contribution) => contribution.deployable === hostName) ||
    context.manifest.shellContributions?.some((contribution) => contribution.deployable === hostName)
  );
}

function buildWebRegistry(outputPath, hostName, contexts) {
  const activeContexts = contexts.filter((context) => contributesToWebHost(context, hostName));
  const manifestImports = activeContexts.map(
    (context) => `import ${toIdentifier(context.contextName)}Manifest from "${context.packageName}/context";`,
  );
  const entries = activeContexts.map(
    (context) => `  {
    contextName: "${context.contextName}",
    packageName: "${context.packageName}",
    manifest: ${toIdentifier(context.contextName)}Manifest as WebContextRegistry[number]["manifest"],
  },`,
  );

  return `${generatedRegistryComment}
import type { WebContextRegistry } from "@chase-sets/platform-runtime/web";

${manifestImports.join("\n")}

export const webContextRegistry = [
${entries.join("\n")}
] as const satisfies WebContextRegistry;
`;
}

function writeFileEnsured(filePath, content) {
  mkdirSync(path.dirname(filePath), { recursive: true });
  writeFileSync(filePath, content, "utf8");
}

function checkExpectedFile(filePath, expectedContent, drift, rootDir) {
  if (!existsSync(filePath)) {
    drift.push(`${normalizePath(path.relative(rootDir, filePath))} is missing`);
    return;
  }

  const currentContent = readFileSync(filePath, "utf8");
  if (currentContent !== expectedContent) {
    drift.push(`${normalizePath(path.relative(rootDir, filePath))} is stale`);
  }
}

function readJsonc(filePath) {
  const content = readFileSync(filePath, "utf8");
  const parsed = ts.parseConfigFileTextToJson(filePath, content);
  if (parsed.error) {
    throw new Error(ts.flattenDiagnosticMessageText(parsed.error.messageText, "\n"));
  }

  return parsed.config;
}

function syncTsconfigBase(workspaces, options) {
  const { check, drift, rootDir } = options;
  const tsconfigBasePath = path.join(rootDir, "tsconfig.base.json");
  const current = readJsonc(tsconfigBasePath);
  current.compilerOptions = {
    ...current.compilerOptions,
    ...ts7CompatibleCompilerOptions,
  };
  for (const option of legacyTsconfigCompilerOptions) {
    delete current.compilerOptions[option];
  }
  for (const option of appBuildSemanticCompilerOptions) {
    delete current.compilerOptions[option];
  }
  current.compilerOptions.paths = buildTsconfigPaths(workspaces, rootDir);
  const content = `${tsconfigBaseComment}${JSON.stringify(current, null, 2)}\n`;

  if (check) {
    checkExpectedFile(tsconfigBasePath, content, drift, rootDir);
    return;
  }

  writeFileSync(tsconfigBasePath, content, "utf8");
}

function syncDeployableRegistries(workspaces, options) {
  const { check, drift, rootDir } = options;
  const contexts = listBoundedContexts(workspaces);

  for (const output of buildGeneratedRegistryOutputs(rootDir)) {
    const content =
      output.kind === "api"
        ? buildApiRegistry(output.outputPath, output.hostName, contexts)
        : output.kind === "worker"
          ? buildWorkerRegistry(output.outputPath, output.hostName, contexts)
          : buildWebRegistry(output.outputPath, output.hostName, contexts);

    if (check) {
      checkExpectedFile(output.outputPath, content, drift, rootDir);
    } else {
      writeFileEnsured(output.outputPath, content);
    }
  }

  for (const legacyPath of buildLegacyPlatformRuntimeRegistryPaths(rootDir)) {
    if (existsSync(legacyPath)) {
      if (check) {
        drift.push(`${normalizePath(path.relative(rootDir, legacyPath))} should be deleted`);
      } else {
        rmSync(legacyPath);
      }
    }
  }
}

function buildEventCorePostgresSchemaContent(schemaSql) {
  return `${generatedSchemaComment}export const eventCorePostgresSchemaSql =\n  ${JSON.stringify(
    normalizeLineEndings(schemaSql),
  )};\n`;
}

function normalizeLineEndings(value) {
  return value.replace(/\r\n/g, "\n");
}

function syncEventCorePostgresSchema(options) {
  const { check, drift, rootDir } = options;
  const schemaSqlPath = path.join(rootDir, "infrastructure", "event-core-postgres", "schema.sql");
  const schemaTsPath = path.join(rootDir, "infrastructure", "event-core-postgres", "schema.ts");
  const schemaSqlExists = existsSync(schemaSqlPath);
  const schemaTsExists = existsSync(schemaTsPath);

  if (!schemaSqlExists && !schemaTsExists) {
    return;
  }

  if (!schemaSqlExists) {
    drift.push(`${normalizePath(path.relative(rootDir, schemaSqlPath))} is missing`);
    return;
  }

  const content = buildEventCorePostgresSchemaContent(readFileSync(schemaSqlPath, "utf8"));

  if (check) {
    checkExpectedFile(schemaTsPath, content, drift, rootDir);
    return;
  }

  writeFileEnsured(schemaTsPath, content);
}

export function syncWorkspaceMetadata(options = {}) {
  const check = options.check ?? false;
  const rootDir = options.rootDir ?? repoRoot;
  const workspaces = options.workspaces ?? listWorkspacePackages({ repoRoot: rootDir });
  const drift = [];

  syncTsconfigBase(workspaces, { check, drift, rootDir });
  syncDeployableRegistries(workspaces, { check, drift, rootDir });
  syncEventCorePostgresSchema({ check, drift, rootDir });

  if (drift.length > 0) {
    throw new Error(
      [
        "Workspace metadata is out of date:",
        ...drift.map((entry) => `- ${entry}`),
        "Run pnpm run sync:workspace-metadata to refresh generated workspace metadata.",
      ].join("\n"),
    );
  }

  return { checked: check, drift };
}

function parseArgs(args) {
  if (args.length === 0) {
    return { check: false };
  }

  if (args.length === 1 && args[0] === "--check") {
    return { check: true };
  }

  throw new Error("Usage: node ./scripts/sync-workspace-metadata.mjs [--check]");
}

function main() {
  const options = parseArgs(process.argv.slice(2));
  const result = syncWorkspaceMetadata(options);
  console.log(result.checked ? "Workspace metadata is current." : "Workspace metadata synchronized.");
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
